def degree_histogram(adjacency: list[list[int]]) -> list[int]:
    """hist[d] = number of nodes with exactly d neighbours."""
    n: int = len(adjacency)
    hist: list[int] = []
    for d in range(n + 1):
        hist.append(0)
    for i in range(n):
        deg: int = 0
        for j in range(n):
            if adjacency[i][j] != 0 and i != j:
                deg += 1
        hist[deg] += 1
    return hist

